export function adaptiveRoleAllocator(agentData) {
  const roles = agentData.map(agent => {
    const performance = evaluatePerformance(agent);
    const metaLearningRate = calculateMetaLearningRate(agent);
    return {
      agentId: agent.agentId,
      role: assignRole(performance, metaLearningRate)
    };
  });
  return roles;
}

function evaluatePerformance(agent) {
  // Simulate performance evaluation logic
  return agent.successRate > 0.85 ? 'high' : 'medium';
}

function calculateMetaLearningRate(agent) {
  // Simulate meta-learning rate calculation logic
  return agent.adjustmentRate * 0.1;
}

function assignRole(performance, metaLearningRate) {
  // Simulate role assignment logic
  if (performance === 'high' && metaLearningRate > 0.05) {
    return 'leader';
  } else if (performance === 'medium') {
    return 'support';
  } else {
    return 'observer';
  }
}